package com.chatsystem.user.controller.report;
import com.chatsystem.shared.mock.MockFixtures;import com.chatsystem.user.*;import com.chatsystem.user.navigation.*;import javafx.scene.Node;import javafx.scene.control.*;import javafx.stage.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class UserReportWorkflowControllerTest extends JavaFxTestSupport{
 @Test void reportSubmissionSearchAndDetailNavigationAreInteractive()throws Exception{onFx(()->{var c=new UserApplicationContext();c.auth().login(MockFixtures.DEMO_EMAIL,MockFixtures.DEMO_PASSWORD,false);var s=new Stage();try{var n=new UserNavigator(s,c);n.start();n.navigate(ViewRequest.of(UserRoute.SPAM_REPORTS));ListView<?> list=control(s,"reportList",ListView.class);assertEquals(2,list.getItems().size());click(s,"newReportButton");Window d=Window.getWindows().stream().filter(w->w!=s&&w.isShowing()).findFirst().orElseThrow();click(d,"submitReportButton");assertFalse(label(d,"feedbackLabel").getText().isBlank());text(d,"messageIdField").setText("1001");text(d,"userIdField").setText("2");text(d,"reasonField").setText("Repeated unwanted message");click(d,"submitReportButton");assertEquals(3,c.reports().getReports().size());assertFalse(d.isShowing());text(s,"reportSearchField").setText("unwanted");click(s,"searchReportsButton");assertFalse(list.getItems().isEmpty());list.getSelectionModel().selectFirst();click(s,"openReportButton");assertEquals(UserRoute.REPORT_DETAIL,n.currentRequest().route());assertFalse(label(s,"reportReasonLabel").getText().isBlank());click(s,"backToReportsButton");assertEquals(UserRoute.SPAM_REPORTS,n.currentRequest().route());}finally{Window.getWindows().stream().filter(w->w!=s).toList().forEach(Window::hide);s.close();}});}
 private static void click(Stage s,String id){control(s,id,Button.class).fire();}private static void click(Window w,String id){((Button)w.getScene().getRoot().lookup("#"+id)).fire();}private static TextInputControl text(Stage s,String id){return control(s,id,TextInputControl.class);}private static TextInputControl text(Window w,String id){return(TextInputControl)w.getScene().getRoot().lookup("#"+id);}private static Label label(Stage s,String id){return control(s,id,Label.class);}private static Label label(Window w,String id){return(Label)w.getScene().getRoot().lookup("#"+id);}private static <T extends Node>T control(Stage s,String id,Class<T> type){Node n=s.getScene().getRoot().lookup("#"+id);assertNotNull(n,id);return type.cast(n);}
}
